CREATE TABLE products (id TEXT PRIMARY KEY, name TEXT NOT NULL, quantity TEXT NOT NULL, price_paise INTEGER NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, stock_quantity INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE orders (id TEXT PRIMARY KEY, customer_name TEXT NOT NULL, phone TEXT NOT NULL, email TEXT, address TEXT NOT NULL, city TEXT NOT NULL, state TEXT NOT NULL, pincode TEXT NOT NULL, subtotal_paise INTEGER NOT NULL, shipping_paise INTEGER NOT NULL, total_paise INTEGER NOT NULL, payment_status TEXT NOT NULL DEFAULT 'pending', order_status TEXT NOT NULL DEFAULT 'pending', whatsapp_status TEXT NOT NULL DEFAULT 'pending', payment_reference TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE order_items (id INTEGER PRIMARY KEY, order_id TEXT NOT NULL REFERENCES orders(id), product_id TEXT NOT NULL REFERENCES products(id), quantity INTEGER NOT NULL, unit_price_paise INTEGER NOT NULL);
